mapper.sql:
WITH scoped AS ( SELECT s.id, s.skill_code, s.skill_name_cn, s.skill_name_en, s.skill_description, s.business_domain, s.capability_domain, s.workspace_id, s.owner, s.creator, coalesce(s.version, 1) AS version, s.create_time, s.update_time, coalesce(rel.state_json::jsonb #>> '{activeChange,status}', s.status, '') AS version_status, coalesce(rel.state_json::jsonb #>> '{environments,ONLINE,sourceId}', '') AS online_version_id, coalesce(rel.state_json::jsonb #>> '{environments,PRT,sourceId}', '') AS preprod_version_id, CASE WHEN rel.revision IS NULL OR rel.revision <= 0 OR jsonb_typeof(rel.state_json::jsonb->'versions') IS DISTINCT FROM 'array' THEN NULL WHEN rel.state_json::jsonb #>> '{activeChange,status}' = 'ACTIVE' THEN 'EDITING' WHEN rel.state_json::jsonb #>> '{activeChange,status}' = 'SEALED' THEN 'SEALED' WHEN rel.state_json::jsonb->'activeChange' IS NULL OR rel.state_json::jsonb->'activeChange' = 'null'::jsonb THEN CASE WHEN jsonb_array_length(rel.state_json::jsonb->'versions') = 0 THEN 'EDITING' ELSE 'SEALED' END ELSE NULL END AS draft_status FROM skill_draft s LEFT JOIN skill_asset_release_state rel ON rel.asset_type = 'SKILL' AND rel.asset_key = s.workspace_id AND rel.deleted = 0 WHERE s.deleted = 0 AND btrim(s.skill_code) <> '' AND s.workspace_id = s.skill_code AND left(s.skill_code, 1) <> '_' AND s.business_domain = #{query.businessDomain} AND s.capability_domain = #{query.capabilityDomain}
AND EXISTS (SELECT 1 FROM entity_relation r WHERE AND btrim() = #{query.specialistId})
AND ( strpos(lower(coalesce(s.skill_code, '')), lower(#{query.keyword})) > 0 OR strpos(lower(coalesce(s.skill_name_cn, '')), lower(#{query.keyword})) > 0 OR strpos(lower(coalesce(s.skill_name_en, '')), lower(#{query.keyword})) > 0 OR strpos(lower(coalesce(s.skill_description, '')), lower(#{query.keyword})) > 0 OR strpos(lower(coalesce(s.business_domain, '')), lower(#{query.keyword})) > 0 OR strpos(lower(coalesce(s.capability_domain, '')), lower(#{query.keyword})) > 0 OR strpos(lower(coalesce(s.owner, '')), lower(#{query.keyword})) > 0 OR EXISTS (SELECT 1 FROM entity_relation r WHERE AND (strpos(lower(), lower(#{query.keyword})) > 0 OR strpos(lower(), lower(#{query.keyword})) > 0)) )
)
